// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 avtc <tarasenkov@gmail.com>

/**
 * The settings pane — the /owl-settings surface.
 *
 * Composes the Claude library's pane stack (controller + tree builder) over
 * the settings consumer's installed handle: the controller drives the wrapped
 * updateSetting (owl's after-change wiring rides inside it), the tree
 * builder runs against the element table the render hook resolves, and the
 * capsules (open/close/invalidate/log) arrive from the wiring — this module
 * never touches a UI API itself.
 *
 * Degrade paths: a surface without field elements (mobile draws no Input or
 * Select) gets a text-only notice naming the manual-JSON locations instead
 * of a broken tree; a missing settings handle (pane requested before the
 * consumer init) refuses to compose and says so through the log capsule.
 */

import {
  captureCtx,
  createPaneController,
  type PaneController,
  type PresetPair,
} from "../../node_modules/avtc-claude-settings-ui/dist/index.js";
import { errDetail } from "../log/err-detail.js";
import { getInstalledSettingsHandle } from "./consumer.js";

/** The pane's pinned id — the render hook filters on it (e.requestId). */
export const SETTINGS_PANE_ID = "owl-settings";

/** The pane's title (pi's modal frame title, carried over). */
export const SETTINGS_PANE_TITLE = "SessionOwl Settings";

/** The manual-JSON degrade notice (surfaces without field elements). */
export const SETTINGS_PANE_MANUAL_JSON =
  "session-owl settings need a terminal surface — edit ~/.claude/avtc-session-owl-settings.json (global) or <project>/.claude/avtc-session-owl-settings.json instead.";

/** The not-initialized degrade notice. */
export const SETTINGS_PANE_NOT_READY = "session-owl settings are not loaded yet — try again in a moment.";

/** The capsules the pane needs (authored in register.ts handlers, data here). */
export interface PaneCapsules {
  uiLog: (text: string) => void;
  uiOpen: (args: {
    id: string;
    title: string;
    focus: boolean;
    closeOnEscape: boolean;
    rows: number;
  }) => Promise<unknown>;
  uiClose: () => void;
  uiInvalidate: () => void;
  /** Places the pane's focus ring on an element (the picker return). */
  uiFocus?: (key: string) => Promise<unknown>;
  /** The engine's settings snapshot ($.settings.read) — the model-row
   *  enrichment reads the user's availableModels from it at pane open. */
  settingsRead: () => Promise<unknown>;
}

/** The model presets every open offers (beside Default): the alias values a
 *  stage spawn accepts verbatim — the enrichment rows append after them. */
const CORE_MODEL_PAIRS: PresetPair[] = [
  ["haiku", "haiku"],
  ["sonnet", "sonnet"],
  ["opus", "opus"],
  ["fable", "fable"],
];

/** Model values the engine reserves that are NOT stage-spawnable ids — an
 *  availableModels entry only ever becomes a picker row when it names
 *  something a spawn could actually run (aliases are already core rows). */
const RESERVED_MODEL_VALUES = new Set([
  "haiku",
  "sonnet",
  "opus",
  "fable",
  "sonnet[1m]",
  "opus[1m]",
  "default",
  "best",
  "opusplan",
]);

/** Rows for the user's own models: each availableModels entry appended as a
 *  `[label, value]` pair — the value verbatim (an id the spawn accepts; the
 *  `provider/<id>` serialization the model-preset path would produce is NOT a
 *  spawnable form here), labeled from modelPicker when the user named the row.
 *  Never throws: anything malformed (non-array, non-string, bad options)
 *  collapses to zero rows, so an odd settings shape degrades to the core
 *  aliases. */
function enrichmentModelPairs(settings: unknown): PresetPair[] {
  if (settings === null || typeof settings !== "object") return [];
  const root = settings as Record<string, unknown>;
  const raw = root.availableModels;
  if (!Array.isArray(raw)) return [];
  const labels = new Map<string, string>();
  const picker = root.modelPicker;
  if (picker !== null && typeof picker === "object") {
    const options = (picker as Record<string, unknown>).options;
    if (Array.isArray(options)) {
      for (const option of options) {
        if (option === null || typeof option !== "object") continue;
        const model = (option as Record<string, unknown>).model;
        const label = (option as Record<string, unknown>).label;
        if (typeof model === "string" && typeof label === "string" && label.length > 0) {
          labels.set(model, label);
        }
      }
    }
  }
  const pairs: PresetPair[] = [];
  const seen = new Set<string>();
  for (const entry of raw) {
    if (typeof entry !== "string") continue;
    const value = entry.trim();
    if (value.length === 0 || seen.has(value)) continue;
    if (RESERVED_MODEL_VALUES.has(value.toLowerCase())) continue;
    seen.add(value);
    pairs.push([labels.get(value) ?? value, value]);
  }
  return pairs;
}

let paneController: PaneController | null = null;

/** Build (once) and open the settings pane. Returns the controller the render
 *  hook reads, or null when the consumer has not initialized (logged). */
export async function ensureSettingsPane(capsules: PaneCapsules): Promise<PaneController | null> {
  const handle = getInstalledSettingsHandle();
  if (handle === null) {
    capsules.uiLog(SETTINGS_PANE_NOT_READY);
    return null;
  }
  if (paneController === null) {
    paneController = createPaneController(handle as never, {
      title: SETTINGS_PANE_TITLE,
      notify: { message: (text) => capsules.uiLog(text), warn: (text) => capsules.uiLog(text) },
      storageLevels: handle.storageLevels,
      cwd: currentCwd,
      onClose: () => capsules.uiClose(),
      onInvalidate: () => capsules.uiInvalidate(),
      onPickerClosed: (rowId) => {
        // pi returns to the item it was changing: re-take the keyboard (Esc
        // handed it back) and put the ring back. In the input-anchored
        // model the ring returns to the FILTER field — its DRAWN key (the
        // current epoch; a stale epoch is never drawn again and the focus
        // wait dies, dropping the keyboard out of the pane); the
        // controller's selection already sits on the edited row.
        const anchored = paneController !== null && paneController.anchorFocusAttempt !== undefined;
        const target = anchored
          ? ((paneController as unknown as { anchorSeatKey?: () => string }).anchorSeatKey?.() ?? "settings-filter:0")
          : rowId;
        void capsules
          .uiOpen({
            id: SETTINGS_PANE_ID,
            title: SETTINGS_PANE_TITLE,
            focus: true,
            closeOnEscape: true,
            rows: 28,
          })
          .then(() => capsules.uiFocus?.(target))
          .catch((err: unknown) => {
            // the pane did not open — say why (the user clicked and sees
            // nothing otherwise)
            capsules.uiLog(`session-owl: settings pane failed to open: ${errDetail(err)}`);
          });
      },
    });
    // The models context for the model-type presets: the platform exposes
    // no model-list API, so the picker offers the engine's DOCUMENTED
    // aliases (the $.model.complete docs' own examples plus fable — the
    // spawn validator's accepted set) as static pairs — plus, appended after
    // them, the user's own availableModels entries (label from modelPicker
    // when the user named one; the read's failure path adds nothing). Full
    // ids and gateway models therefore become real rows, the value staying
    // round-trippable through the files.
    let enrichment: PresetPair[] = [];
    try {
      enrichment = enrichmentModelPairs(await capsules.settingsRead());
    } catch (err) {
      // an unreadable settings snapshot never blocks the pane — but the
      // read failure is still said
      capsules.uiLog(`session-owl: settings pane model enrichment failed: ${errDetail(err)}`);
    }
    captureCtx({
      models: [],
      enabledModelPatterns: null,
      staticModelPairs: [...CORE_MODEL_PAIRS, ...enrichment],
      cwd: currentCwd,
    });
    await paneController.prepare();
  }
  await capsules.uiOpen({
    id: SETTINGS_PANE_ID,
    title: SETTINGS_PANE_TITLE,
    focus: true,
    closeOnEscape: true,
    rows: 28,
  });
  return paneController;
}

/** The cwd the pane's project saves target (set by the consumer init). */
let currentCwd = "";

/** Record the session cwd (called by the settings consumer init). */
export function setPaneCwd(cwd: string): void {
  currentCwd = cwd;
}

/** The controller for the render hook (null before the first open). */
export function getSettingsPaneController(): PaneController | null {
  return paneController;
}

/** The text-only tree for surfaces without field elements (mobile). */
export function manualJsonNoticeTree(els: { Text: (props: Record<string, unknown>) => unknown }): unknown {
  return els.Text({ key: "owl-settings-degrade", children: SETTINGS_PANE_MANUAL_JSON });
}

/** Test seam: full reset. */
export function _resetSettingsPaneForTest(): void {
  paneController = null;
  currentCwd = "";
}

files.host/stage/agents.ts:
// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 avtc <tarasenkov@gmail.com>

// The three stage agent types' specs. Platform-verified:
//   spec `name` is the BARE short form (observer/builder/selector); the
//   namespaced pair `<plugin>:<name>` is what spawn takes as subagentType
//   and what agent.offer sees;
//   `description` is required (a host check rejects the registration
//   without it);
//   `tools` is an EXPLICIT name set — the declaring agent sees only it
//   (pi parity);
//   `maxTurns` — pi sets NO cap anywhere (observer/builder/selector run
//   NO_TURN_LIMIT, bounded by per-call maxTokens + timeoutMs + the
//   no-progress stops; goal-extract is a one-shot completer), so the spec
//   carries none — the engine's own default governs;
//   `omitClaudeMd` — the stage context carries its prompt alone;
//   `background` — every spawn runs in the background.
//
// The system prompts arrive as INPUTS (the vendored prompt modules supply
// them; builder/selector prompts are settings-shaped) so this module stays
// import-free — it must sit inside the hooks closure.
import type { StageName } from "./runs.js";

/** The plugin's name as the engine namespaces it under. */
const PLUGIN_NAME = "session-owl";

/** The `subagentType` string for a stage (the namespaced `<plugin>:<name>`). */
export function stageSubagentType(stage: StageName): string {
  return `${PLUGIN_NAME}:${stage}`;
}

/** Every agent type this plugin declares (the bare short forms). */
export const STAGE_AGENT_NAMES: readonly StageName[] = ["observer", "builder", "selector"];

/** The mcp tool name as the model sees it. */
export function stageToolName(short: string): string {
  return `mcp__${PLUGIN_NAME}__${short}`;
}

/** The graph tools the Builder owns: the five mutate tools + the three read
 *  views + the try_finish convergence gate (pi's makeBuilderTools — all
 *  nine; the gate's ok-answer is how the run detects convergence). */
export const BUILDER_GRAPH_TOOLS: readonly string[] = [
  "mkdir",
  "mv",
  "merge",
  "supersede",
  "set_meta",
  "ls",
  "cat",
  "find",
  "try_finish",
];

/** The graph tools the Selector owns: its four-tool mutation subset + the
 *  read views + the try_finish convergence gate (pi's makeSelectorTools'
 *  graph set — all eight). */
export const SELECTOR_GRAPH_TOOLS: readonly string[] = [
  "mkdir",
  "mv",
  "merge",
  "set_meta",
  "ls",
  "cat",
  "find",
  "try_finish",
];

/** The engine built-ins the Selector additionally reads the live project
 *  with (pi's fs_* aliases over its own read/grep/find/ls built-ins — the
 *  Claude counterparts by name). */
export const SELECTOR_FILE_TOOLS: readonly string[] = ["Read", "Grep", "Glob", "LS"];

/** The stage-model settings slice the spec builder reads (structural — the
 *  core's SessionOwlConfig satisfies it; declared locally so no core import
 *  rides into the hooks closure). */
export interface StageModelSettings {
  defaultModel: string | null;
  defaultThinkingLevel: string | null;
  observerModel: string | null;
  observerThinkingLevel: string | null;
  builderModel: string | null;
  builderThinkingLevel: string | null;
  selectorModel: string | null;
  selectorThinkingLevel: string | null;
}

/** One agent type's spec — the subset of the engine's AgentSpec this port
 *  sets (spelled structurally; the register wiring passes it through). */
export interface StageAgentSpec {
  name: string;
  description: string;
  prompt: string;
  tools: readonly string[];
  model: string | undefined;
  effort: string | number | undefined;
  omitClaudeMd: true;
  background: true;
}

/** The spec descriptions (required by the host's registration check). */
const STAGE_DESCRIPTIONS: Record<StageName, string> = {
  observer: "session-owl's memory Observer: reads a session chunk and records observations",
  builder: "session-owl's memory Builder: restructures the observation graph",
  selector: "session-owl's memory Selector: prunes and re-parents the graph's root view",
};

/** Resolve the stage's model from the chain (pi's `resolveStageModel`'s
 *  settings tier): stage setting → default → undefined (the session's). */
export function stageModelFromSettings(settings: StageModelSettings, stage: StageName): string | undefined {
  const perStage: Record<StageName, string | null> = {
    observer: settings.observerModel,
    builder: settings.builderModel,
    selector: settings.selectorModel,
  };
  return perStage[stage] ?? settings.defaultModel ?? undefined;
}

/** Map a thinking level to the engine's effort. "off" and
 *  "minimal" omit the field (the engine's default); the levels pass through;
 *  null (inherit) omits too — the session's effort then governs.  */
export function effortFromThinking(level: string | null): string | undefined {
  if (level === null || level === "off" || level === "minimal") return undefined;
  return level;
}

/** The stage's effort from the chain: stage level → default → undefined. */
export function stageEffortFromSettings(settings: StageModelSettings, stage: StageName): string | undefined {
  const perStage: Record<StageName, string | null> = {
    observer: settings.observerThinkingLevel,
    builder: settings.builderThinkingLevel,
    selector: settings.selectorThinkingLevel,
  };
  return effortFromThinking(perStage[stage] ?? settings.defaultThinkingLevel);
}

/** The exact tool set a stage's agent type sees (mcp-prefixed graph tools;
 *  the Observer's single record tool; the Selector's engine file reads). */
/** The engine's built-in report tool every background agent delivers
 *  through. AgentSpec.tools is EXHAUSTIVE — a call to anything not on the
 *  list is refused — so the handback itself must ride every stage's list
 *  or ask-mode sessions deny it. */
export const HANDBACK_TOOL = "SubagentHandback";

export function agentSpecTools(stage: StageName): readonly string[] {
  if (stage === "observer") return [stageToolName("record_observations"), HANDBACK_TOOL];
  const graph = stage === "builder" ? BUILDER_GRAPH_TOOLS : SELECTOR_GRAPH_TOOLS;
  const tools = graph.map(stageToolName);
  if (stage === "selector") {
    tools.push(...SELECTOR_FILE_TOOLS);
    // the conditional bridge tool rides the spec (AgentSpec.tools is
    // exhaustive — a call to anything else is refused); its body binds only
    // when the todo bridge is live, else the no-executor deny answers
    tools.push(stageToolName("todo_list"));
  }
  tools.push(HANDBACK_TOOL);
  return tools;
}

/** The settings slice with nothing set — every stage inherits the session's
 *  model/effort (the fallback default; the settings wiring passes the
 *  live slice later). */
export function noStageModelSettings(): StageModelSettings {
  return {
    defaultModel: null,
    defaultThinkingLevel: null,
    observerModel: null,
    observerThinkingLevel: null,
    builderModel: null,
    builderThinkingLevel: null,
    selectorModel: null,
    selectorThinkingLevel: null,
  };
}

/** Build the three specs. The prompts are the vendored stage system prompts
 *  (verbatim — pi parity); the settings slice resolves model/effort. */
export function stageAgentSpecs(input: {
  observerPrompt: string;
  builderPrompt: string;
  selectorPrompt: string;
  settings: StageModelSettings;
}): StageAgentSpec[] {
  const prompts: Record<StageName, string> = {
    observer: input.observerPrompt,
    builder: input.builderPrompt,
    selector: input.selectorPrompt,
  };
  return STAGE_AGENT_NAMES.map((stage) => ({
    name: stage,
    description: STAGE_DESCRIPTIONS[stage],
    prompt: prompts[stage],
    tools: agentSpecTools(stage),
    model: stageModelFromSettings(input.settings, stage),
    effort: stageEffortFromSettings(input.settings, stage),
    omitClaudeMd: true as const,
    background: true as const,
  }));
}

