// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 avtc <tarasenkov@gmail.com>

// The shared notify adapter — the port of pi's src/notify.ts surface.
// pi wraps `ctx.ui.notify(message, level)`; the platform's equivalent is
// `$.ui.log(text)`, a dim transcript line the model never reads. Three
// mechanical differences the adapter owns once for every call site:
//
//   line  ONE CALL PER MESSAGE: the line breaks of a multi-line message
//         are replaced by " | " and empty lines dropped — the engine's
//         block draw turns an embedded newline into U+FFFD at the terminal
//         (the engine receipt keeps our real newlines intact; the
//         conversion is at draw), while one-call-per-line flooded the
//         screen with a plugin bullet per row.
//   level pi's per-level color/theming has no ui.log equivalent: the level
//         is dropped here and the text passes through byte-identical apart
//         from the delimiter join (pi's textual severity lives in the
//         message texts themselves). The cosmetic loss is recorded in the
//         port's gaps register — never compensated by rewriting.
//
// The capsule rule: the ui.log call site is authored in the register
// handler (`$.ui.log(text)` spelled literally); this adapter receives the
// capsule and never sees `$`.
export type NotifyLevel = "info" | "warning" | "error";

/** pi's notify transport, level-carrying — pi's argument order
 *  (`notify(ctx, message, level)`), shared with the run seams' StageNotify
 *  and the compaction hook's notify dep so every surface spells it alike. */
export type NotifyFn = (text: string, level: NotifyLevel) => void;

/** pi's confirm transport (title + message → boolean). */
export type ConfirmFn = (title: string, message: string) => Promise<boolean>;

/** Build the notify adapter over the ui.log capsule. One call per message:
 *  the message's lines (empty ones dropped) joined by the " | " delimiter,
 *  the level dropped (the cosmetic gap). */
export function makeNotifyAdapter(uiLog: (text: string) => void): NotifyFn {
  return (text, _level) => {
    uiLog(
      text
        .split("\n")
        .filter((line) => line.trim() !== "")
        .join(" | "),
    );
  };
}

files.core/src/compaction/summary.ts:
// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 avtc <tarasenkov@gmail.com>

// renderSummary: the mechanical compaction-summary renderer. Produces the
// text Pi injects post-compaction — the agent's memory. Sections: a # Memory
// header + legend + owl_recall hint, the verbatim initial prompt, the active-set
// root one-liners (selected tree or observations root), and recently-touched
// files. Obsolete roots excluded; never truncated (bounded by the
// Selector/Builder try_finish, not here).

import {
  directObsSizeHint,
  formatNodeLine,
  RENDER_LEGEND,
  type RenderableNode,
  renderTreeTotal,
  type SizeHintObservation,
} from "../format/render.js";
import { orderedNonObsoleteRoots } from "../graph/read-tools.js";
import type { SerializedObservation, SerializedSelection } from "../store/codecs.js";
import { renderTouchedFiles, type TouchedFile } from "./touched-files.js";

/** Which tree the active-set renders. */
export type SummaryRenderMode = "selected-root" | "observations-root";

/** The structural graph shape renderSummary reads (source roots for
 *  observations-root mode + the selected-root null-tree fallback). */
export interface SummaryGraph {
  nodes: ReadonlyMap<string, RenderableNode>;
  /** Observations by id — the root one-liners' direct-obs size hints resolve
   *  here (both modes: the selected tree carries structure only, its observation
   *  ids belong to the source graph). Omitted when the caller has no access
   *  (no size segments then). */
  observations?: ReadonlyMap<string, SizeHintObservation>;
}

/** Inputs to renderSummary. */
export interface RenderSummaryArgs {
  /** The source graph (read for observations-root mode + selected-root fallback). */
  graph: SummaryGraph;
  /** The Selector's persisted selected tree (null = not built yet / failed). */
  selectedTree: SerializedSelection | null;
  /** The verbatim initial prompt observation (null = never captured). */
  oInitialPrompt: SerializedObservation | null;
  /** The active render mode. */
  renderMode: SummaryRenderMode;
  /** Recently-touched files (already extracted + deduped). */
  touchedFiles: readonly TouchedFile[];
  /** Compactions so far this session (the tree-total footer's maturity signal). */
  compactionCount: number;
}

const MEMORY_HEADING = "# Memory";
const PREAMBLE = "Your session memory — the top level of a tree; each id opens deeper detail via owl_recall.";
/** The recall-first guidance section (protected text — changes require owner
 *  approval). Sits between the legend and the initial prompt. */
const MEMORY_USE_HEADING = "## Memory use";
const MEMORY_USE =
  'The root view is a navigation index into retained session memory: the lines name what exists; the detail, evidence, rationale, and results live in the tree behind them, across the whole session (see the totals). Recall before relying on session-derived understanding: search memory, or expand a visible related id — a complete-looking label still summarizes only the surface, and relevant context often sits deeper than the root. Use {"ids":["n23"]} to expand, {"query":"…"} to search, and add "fullDetails":true when exact messages, tool output, or rationale matter.';
const LEGEND_PREFIX = "Legend: ";
const INITIAL_PROMPT_HEADING = "## Initial prompt";
const ACTIVE_SET_HEADING = "## Active set";
const NO_TOUCHED = 0;
const NO_TOUCHED_PLACEHOLDER = "(none)";

const TOUCHED_HEADING = "## Recently touched";
const NO_INITIAL_PROMPT = "(none captured yet)";
const NO_NODES = 0;

/** Stand-in observations map when the caller passes no observation access —
 *  direct-obs size lookups simply miss (no size segments). */
const EMPTY_OBSERVATIONS: ReadonlyMap<string, SizeHintObservation> = new Map();

/**
 * Render the compaction summary text. Mechanical, never truncated. The
 * active-set roots: selected-root mode renders the selected tree (falling back
 * to the source roots when no selected tree exists yet); observations-root mode
 * renders the source graph's non-obsolete roots. nGoal is always first.
 */
export function renderSummary(args: RenderSummaryArgs): string {
  const lines: string[] = [];
  lines.push(MEMORY_HEADING);
  lines.push(PREAMBLE);
  lines.push(`${LEGEND_PREFIX}${RENDER_LEGEND}`);
  lines.push("");

  lines.push(MEMORY_USE_HEADING);
  lines.push(MEMORY_USE);
  lines.push("");

  lines.push(INITIAL_PROMPT_HEADING);
  lines.push(args.oInitialPrompt === null ? NO_INITIAL_PROMPT : args.oInitialPrompt.summary);
  lines.push("");

  lines.push(ACTIVE_SET_HEADING);
  const sizeHints = args.graph.observations ?? EMPTY_OBSERVATIONS;
  for (const root of activeSetRoots(args)) {
    lines.push(formatNodeLine(root, { obsSize: directObsSizeHint(root, sizeHints) }));
  }
  // The tree-total footer: the scale of everything retained (the source graph,
  // incl. obsolete) behind this top level. Skipped when the tree is empty
  // (nothing to total).
  if (args.graph.nodes.size > NO_NODES) {
    lines.push(renderTreeTotal({ nodes: args.graph.nodes, observations: sizeHints }, args.compactionCount));
  }
  lines.push("");

  lines.push(TOUCHED_HEADING);
  if (args.touchedFiles.length === NO_TOUCHED) {
    lines.push(NO_TOUCHED_PLACEHOLDER);
  } else {
    for (const line of renderTouchedFiles(args.touchedFiles)) {
      lines.push(line);
    }
  }

  return lines.join("\n");
}

/** The root nodes to render in the active-set section, per renderMode. */
function activeSetRoots(args: RenderSummaryArgs): RenderableNode[] {
  if (args.renderMode === "selected-root" && args.selectedTree !== null) {
    return selectedRoots(args.selectedTree);
  }
  // observations-root mode, OR selected-root with no selected tree yet (fall
  // back to the source roots so the summary is never empty on the first run).
  return sourceRoots(args.graph);
}

/** Non-obsolete source roots, nGoal first then time (oldest first). */
function sourceRoots(graph: SummaryGraph): RenderableNode[] {
  // nGoal first, the rest by time (oldest first; nIrrelevant is source-absent).
  return orderedNonObsoleteRoots(graph.nodes.values());
}

/** Non-obsolete selected-tree roots, nGoal first, nIrrelevant last. */
function selectedRoots(tree: SerializedSelection): RenderableNode[] {
  // nGoal first, nIrrelevant last, the rest by time (oldest first).
  return orderedNonObsoleteRoots(tree.nodes);
}

files.core/src/compaction/touched-files.ts:
// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 avtc <tarasenkov@gmail.com>

// Touched-files extraction: scans the active branch (getBranch — NOT getEntries,
// which mixes all branches) for read/write/edit toolCall entries since a cut
// entry, excludes bash-mediated ops, dedups by path (write > edit > read
// dominance, latest timestamp kept), and renders <Mon> <DD> <HH:MM>
// read|write|edit <path>[:line-range] oldest-first. Surfaces to the Selector
// input AND the rendered compaction summary.

import type { SessionEntry, SessionMessageEntry } from "@earendil-works/pi-coding-agent";
import { formatDayTime, singleLine, toStoredTimestamp } from "../format/render.js";

/** Narrow port over the session manager for touched-files (the active branch +
 *  the current leaf). Injected so tests pass a fake; production passes the
 *  ExtensionContext's sessionManager. */
export interface TouchedFilesContext {
  /** The current leaf entry id (null at session start before any entry). */
  getLeafId: () => string | null;
  /** The active branch path entries (NOT all-branches getEntries). Accepts the
   *  leaf id or undefined for the current leaf. */
  getBranch: (leafId?: string) => SessionEntry[];
}

/** One touched file: its path, the last-touch timestamp (stored contract), op,
 *  and (for read-only files) the merged line ranges read. */
export interface TouchedFile {
  path: string;
  timestamp: string;
  op: "write" | "edit" | "read";
  /** The merged read ranges (overlapping/adjacent unioned), present only when
   *  the file was only ever read (no write/edit dominated). `end: null` = open. */
  lineRanges?: readonly LineRange[];
}

/** A line range read from a `read` tool's offset/limit args (1-indexed). */
export interface LineRange {
  start: number;
  end: number | null;
}

/** All file-touching tool names (bash is deliberately excluded — unbounded).
 *  The tool name IS the op (read/write/edit map 1:1). */
const FILE_TOOLS = new Set(["read", "write", "edit"]);

const NO_CUT: string | null = null;
const NO_PATH_LENGTH = 0;
const INDEX_NOT_FOUND = -1;
const FIRST_ENTRY = 0;

/** Extract deduped touched files from the active branch's compacted block:
 *  the entries strictly BEFORE `cutEntryId` (the current compaction's first
 *  retained entry), bounded below by the previous compaction on the path (so a
 *  mid-session list reflects activity since the last compaction, not the whole
 *  history). `cutEntryId === null` (background, no compaction cut) scans from
 *  the previous compaction to the current leaf. Bash ops are excluded; paths
 *  are deduped (write > edit > read dominance; the latest timestamp wins for
 *  ordering). A file read at several ranges keeps every range — overlapping /
 *  adjacent ones merged — so the list shows all inspected sections. Oldest-first. */
export function extractTouchedFiles(ctx: TouchedFilesContext, cutEntryId: string | null): TouchedFile[] {
  const entries = ctx.getBranch(ctx.getLeafId() ?? undefined);
  const [start, end] = compactedRange(entries, cutEntryId);

  // Accumulate per path: the dominant op, the latest timestamp (for ordering),
  // and every read range (so a file read at several sections keeps them all).
  const accums = new Map<string, PathAccum>();
  for (let i = start; i < end; i += 1) {
    const entry = entries[i];
    if (entry === undefined) continue;
    for (const touch of fileTouches(entry)) {
      const existing = accums.get(touch.path);
      if (existing === undefined) {
        accums.set(touch.path, {
          path: touch.path,
          latestTimestamp: touch.timestamp,
          op: touch.op,
          readRanges: touch.lineRange !== undefined ? [touch.lineRange] : [],
        });
      } else {
        existing.op = dominantOp(existing.op, touch.op);
        if (touch.timestamp >= existing.latestTimestamp) existing.latestTimestamp = touch.timestamp;
        if (touch.lineRange !== undefined) existing.readRanges.push(touch.lineRange);
      }
    }
  }

  // Resolve each path: write/edit dominate (no range); read-only files merge
  // their accumulated ranges into the final entry (undefined when none).
  const files: TouchedFile[] = [];
  for (const a of accums.values()) {
    files.push({
      path: a.path,
      timestamp: a.latestTimestamp,
      op: a.op,
      lineRanges: a.op === "read" && a.readRanges.length > 0 ? mergeRanges(a.readRanges) : undefined,
    });
  }
  return files.sort((x, y) => x.timestamp.localeCompare(y.timestamp));
}

/** Per-path accumulator: the dominant op, latest timestamp, and every read range. */
interface PathAccum {
  path: string;
  latestTimestamp: string;
  op: TouchedFile["op"];
  readRanges: LineRange[];
}

/** The stronger action wins (write > edit > read): a file created/overwritten
 *  is more significant than one merely edited, which is more significant than
 *  one merely read. */
function dominantOp(a: TouchedFile["op"], b: TouchedFile["op"]): TouchedFile["op"] {
  if (a === "write" || b === "write") return "write";
  if (a === "edit" || b === "edit") return "edit";
  return "read";
}

/** Union overlapping or adjacent ranges (start ≤ prev.end + 1) into a compact
 *  set. An open end (null) absorbs everything after it and stays open. The
 *  result is sorted by start with no overlaps. */
function mergeRanges(ranges: readonly LineRange[]): LineRange[] {
  if (ranges.length <= 1) return [...ranges];
  const sorted = [...ranges].sort((a, b) => a.start - b.start);
  const merged: LineRange[] = [];
  for (const r of sorted) {
    const last = merged[merged.length - 1];
    if (last !== undefined && last.end !== null && r.start <= last.end + 1) {
      // adjacent or overlapping, finite last end — extend it
      last.end = r.end === null ? null : Math.max(last.end, r.end);
    } else if (last !== undefined && last.end === null) {
    } else {
      merged.push({ start: r.start, end: r.end });
    }
  }
  return merged;
}

/** The [start, end) range of the compacted block: entries strictly before the
 *  cut (`cutEntryId` exclusive), bounded below by the previous compaction entry
 *  on the path (its position + 1 — the summary entry itself carries no file
 *  touches). `cutEntryId === null` → end = branch length (background, scan to
 *  the current leaf). Falls back to the whole branch when no previous
 *  compaction is found. */
function compactedRange(entries: SessionEntry[], cutEntryId: string | null): [number, number] {
  const cutIndex = cutEntryId === NO_CUT ? entries.length : entries.findIndex((e) => e.id === cutEntryId);
  const end = cutIndex === INDEX_NOT_FOUND ? entries.length : cutIndex; // exclusive of the cut entry
  // the previous compaction on the path bounds the block below (its summary
  // entry carries no file touches; start strictly after it).
  let start = FIRST_ENTRY;
  for (let i = end - 1; i >= FIRST_ENTRY; i -= 1) {
    const entry = entries[i];
    if (entry === undefined) continue;
    if (entry.type === "compaction") {
      start = i + 1;
      break;
    }
  }
  return [start, end];
}

/** A message entry is a candidate if it carries toolCall parts. */
export function isMessageEntry(entry: SessionEntry): entry is SessionMessageEntry {
  return entry.type === "message";
}

/** A message whose content is an array of parts (assistant/toolResult; not custom/string). */
interface PartedMessage {
  content: readonly unknown[];
}

/** Whether an AgentMessage carries parted content (assistant/toolResult). */
function isPartedMessage(message: unknown): message is PartedMessage {
  return (
    typeof message === "object" &&
    message !== null &&
    "content" in message &&
    Array.isArray((message as { content: unknown }).content)
  );
}

/** A raw touch from one tool call: path + op + timestamp + (for reads) the
 *  single range that call covered. Accumulated + resolved into a TouchedFile. */
interface FileTouch {
  path: string;
  timestamp: string;
  op: TouchedFile["op"];
  lineRange?: LineRange;
}

/** Extract the file touches (path + op + timestamp + optional read range) from
 *  one entry's toolCalls. The tool name IS the op (read/write/edit). */
function fileTouches(entry: SessionEntry): FileTouch[] {
  if (!isMessageEntry(entry)) return [];
  const message = entry.message;
  if (!isPartedMessage(message)) return [];
  const timestamp = toStoredTimestamp(entry.timestamp);
  const touches: FileTouch[] = [];
  for (const part of message.content) {
    if (typeof part !== "object" || part === null) continue;
    const typed = part as { type?: string; name?: string; arguments?: Record<string, unknown> };
    if (typed.type !== "toolCall") continue;
    const name = typed.name;
    if (name === undefined || !FILE_TOOLS.has(name)) continue;
    const args = typed.arguments ?? {};
    const path = args.path;
    if (typeof path !== "string" || path.length === NO_PATH_LENGTH) continue;
    const op = name as TouchedFile["op"];
    touches.push({ path, timestamp, op, lineRange: op === "read" ? readLineRange(args) : undefined });
  }
  return touches;
}

/** The line range a `read` covered, from its offset/limit args (1-indexed).
 *  Returns undefined when the read had no offset (a from-the-top read, full or
 *  limit-bounded — no meaningful section to cite). offset+limit → start-end;
 *  offset only → start- (open). */
function readLineRange(args: Record<string, unknown>): LineRange | undefined {
  const offset = args.offset;
  if (typeof offset !== "number" || !Number.isFinite(offset) || offset < 1) return undefined;
  const start = Math.floor(offset);
  const limit = args.limit;
  if (typeof limit !== "number" || !Number.isFinite(limit) || limit < 1) {
    return { start, end: null };
  }
  return { start, end: start + Math.floor(limit) - 1 };
}

/** Render touched files as `<Mon> <DD> <HH:MM> read|write|edit <path>[:ranges]`
 *  lines (one per file). */
export function renderTouchedFiles(files: readonly TouchedFile[]): string[] {
  return files.map(renderTouchedFile);
}

/** Render a touched-file line as "<Mon> <DD> <HH:MM> <op> <path>[:ranges]". The op
 *  is the word (read/write/edit); a read-only file appends its merged ranges
 *  (e.g. ":1-50,100-200") to the path. */
function renderTouchedFile(f: TouchedFile): string {
  const rangeSuffix = f.op === "read" ? formatRangesSuffix(f.lineRanges) : "";
  return `${formatDayTime(f.timestamp)} ${f.op} ${singleLine(f.path)}${rangeSuffix}`;
}

/** ":1-50,100-200" for merged ranges (comma-joined), "" when there are none.
 *  A single-line range renders as ":N"; an open end as ":N-". */
function formatRangesSuffix(ranges: readonly LineRange[] | undefined): string {
  if (ranges === undefined || ranges.length === 0) return "";
  return `:${ranges.map(formatRange).join(",")}`;
}

/** "start-end", "start" (single line), or "start-" (open end). */
function formatRange(range: LineRange): string {
  if (range.end === null) return `${range.start}-`;
  if (range.end === range.start) return `${range.start}`;
  return `${range.start}-${range.end}`;
}

files.core/src/compaction/usage-map.ts:
// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 avtc <tarasenkov@gmail.com>

// Map session-owl's per-phase usage (PhaseUsage) into pi's `Usage` shape so the
// session_before_compact hook can return `compaction.usage` (the bench's
// metric, measurable per session-owl arm). pi's `addUsageToTotals`
// has NO nullish guards, so every field MUST be a finite number (0, never
// undefined/omitted) and `cost` MUST be an object with `total: number`.
//
// Shape notes (session-owl → pi-ai Usage):
//  - input/output/cacheRead/cacheWrite carry straight through.
//  - `totalTokens` (pi-ai) is the per-agent context-window consumption; session-owl's
//    PhaseUsage doesn't accumulate it, so we derive input+output+cacheRead+cacheWrite
//    (the honest token total — never 0 for a non-empty phase, never undefined).
//  - `cost` is flat per-phase in session-owl (PhaseUsage.cost = cost.total); the
//    per-bucket cost.{input,output,cacheRead,cacheWrite} are NOT tracked, so they
//    emit 0 (honest) while cost.total carries the real number addUsageToTotals reads.

import type { Usage } from "@earendil-works/pi-ai";
import type { PhaseUsage, UsageLedger } from "../store/codecs.js";

/** Map one phase's cumulative usage into pi's `Usage` shape. All fields finite. */
export function phaseUsageToUsage(p: PhaseUsage): Usage {
  return {
    input: p.input,
    output: p.output,
    cacheRead: p.cacheRead,
    cacheWrite: p.cacheWrite,
    // session-owl doesn't track per-phase totalTokens → derive the token sum.
    totalTokens: p.input + p.output + p.cacheRead + p.cacheWrite,
    // per-bucket costs aren't tracked; total is the real number pi reads.
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: p.cost },
  };
}

/** Sum observe + build + select into the aggregate `Usage` for `compaction.usage`. */
export function aggregateLedgerUsage(delta: UsageLedger): Usage {
  const sum = (sel: (p: PhaseUsage) => number): number => sel(delta.observe) + sel(delta.build) + sel(delta.select);
  const input = sum((p) => p.input);
  const output = sum((p) => p.output);
  const cacheRead = sum((p) => p.cacheRead);
  const cacheWrite = sum((p) => p.cacheWrite);
  return {
    input,
    output,
    cacheRead,
    cacheWrite,
    totalTokens: input + output + cacheRead + cacheWrite,
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: sum((p) => p.cost) },
  };
}

/** Per-stage breakdown (observe/build/select each → Usage) for the freeform `details`
 *  field — feeds the bench's per-stage table. Additive over the existing
 *  `lastCompactionLedger` (which is cumulative, not this-compaction's delta).  */
export function ledgerToStageUsages(delta: UsageLedger): { observe: Usage; build: Usage; select: Usage } {
  return {
    observe: phaseUsageToUsage(delta.observe),
    build: phaseUsageToUsage(delta.build),
    select: phaseUsageToUsage(delta.select),
  };
}

files.core/src/format/chunk.ts:
// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 avtc <tarasenkov@gmail.com>

import type { AgentMessage } from "@earendil-works/pi-agent-core";
import type { AssistantMessage, TextContent, ToolCall, ToolResultMessage, UserMessage } from "@earendil-works/pi-ai";
import type {
  BranchSummaryEntry,
  CustomMessageEntry,
  SessionEntry,
  SessionMessageEntry,
} from "@earendil-works/pi-coding-agent";
import { CHARS_PER_TOKEN_ESTIMATE } from "../types.js";
import { stripAnsi } from "./sanitize.js";

/**
 * One rendered tag-block in the Observer's XML-tagged chunk format. A block is
 * the atomic citation unit (carries the entryId attribute). Within an entry's group, a
 * tool-call block is always immediately followed by its result block so the
 * pair reads as one adjacency unit.
 */
export interface RenderBlock {
  readonly text: string;
  readonly entryId: string;
}

/**
 * One entry's rendered blocks kept together as an atomic chunking unit (a whole
 * entry is never split across chunks). An assistant entry carrying tool calls
 * absorbs each call's matched tool-result entry into its group.
 */
export interface RenderGroup {
  readonly blocks: readonly RenderBlock[];
}

export interface ChunkOptions {
  /** Emit a chunk once accumulated entry-groups reach this many tokens (chars/4). */
  readonly tokenThreshold: number;
  /** Cap each tool arg/result block to this many tokens (head/tail + marker); null = no cap. */
  readonly toolBlockCapTokens: number | null;
  /** Include non-redacted thinking blocks (redacted always skipped). */
  readonly includeThinking: boolean;
  /** Emit the `entryId=id` attribute on each tag (the Observer cites source ids;
   *  recall consumers — Builder/Selector/agent — have no use for raw entry ids). */
  readonly includeEntryId: boolean;
  /** Renumber the chunk's `entryId=` attributes as chunk-scoped sequential shorts
   *  form in first-appearance order) for the model to cite — long stored ids
   *  are costly to copy and easy to mangle. The chunk reports the mapping
   *  via `RenderedChunk.idMap` (short → stored id); `allowedIds` and the
   *  first/last range stay the stored ids. Default: ids as stored. */
  readonly shortEntryIds?: boolean;
}

export interface RenderedChunk {
  readonly text: string;
  readonly allowedIds: ReadonlySet<string>;
  /** The lowest-branch-position source entry id in this chunk — the start of the
   *  chunk's coverage range (coversFromId). Captured at flush time. */
  readonly firstEntryId: string;
  /** The highest-branch-position source entry id in this chunk — used to advance
   *  the observer frontier over the contiguous successful prefix. Captured at
   *  flush time (blocks are in entry order) so callers need not re-scan the gap. */
  readonly lastEntryId: string;
  /** Present when `shortEntryIds` rendered the chunk: this chunk's short →
   *  stored id map (the validator accepts either form and persists stored). */
  readonly idMap?: ReadonlyMap<string, string>;
}

// --- constants --------------------------------------------------------------

/** Entry types the Observer renders as citation sources (the chunk input). */
const RENDERABLE_ENTRY_TYPES: ReadonlySet<string> = new Set(["message", "custom_message", "branch_summary"]);

/** Whether an entry is an Observer-renderable source (message/custom_message/branch_summary). */
export function isRenderableEntry(entry: SessionEntry): boolean {
  return RENDERABLE_ENTRY_TYPES.has(entry.type);
}

const TRUNCATION_MARKER = "[…truncated…]";
const THINKING_PREFIX_PATTERN = /^Thinking:\s*/;
const ATTR_ERROR = "error";
/** Separator between rendered blocks (each tag on its own line — readability for
 *  the Observer LLM and recall consumers; the inner text is already cleaned). */
export const BLOCK_SEP = "\n";
const FIRST_INDEX = 0;

// --- sanitization & truncation ---------------------------------------------

function sanitizeThinking(text: string): string {
  return stripAnsi(text).replace(THINKING_PREFIX_PATTERN, "");
}

/** Cap a tool block's inner text to `capTokens` tokens (chars/4): keep head + tail. null = no cap. */
function capBlock(text: string, capTokens: number | null): string {
  if (capTokens === null) return text;
  const budgetChars = capTokens * CHARS_PER_TOKEN_ESTIMATE;
  if (text.length <= budgetChars) return text;
  const half = Math.trunc(budgetChars / 2);
  const head = text.slice(0, half);
  const tail = text.slice(text.length - half);
  return `${head}${TRUNCATION_MARKER}${tail}`;
}

/** Extract joinable text from a content array (skip images), then strip ANSI. */
function cleanText(content: string | readonly (TextContent | { readonly type: string })[]): string {
  const raw =
    typeof content === "string"
      ? content
      : content
          .filter((part): part is TextContent => part.type === "text")
          .map((part) => part.text)
          .join("");
  return stripAnsi(raw);
}

// --- block constructors (final inner text already cleaned/capped) -----------

/** A simple-tag block: <TAG [entryId=id]>inner</TAG>. Shared by the plain text/
 *  thinking tags (they differ only in the tag name). */
function tagBlock(tag: string, id: string, inner: string, includeEntryId: boolean): RenderBlock {
  const attr = includeEntryId ? ` entryId=${id}` : "";
  return { entryId: id, text: `<${tag}${attr}>${inner}</${tag}>` };
}

const uBlock = (id: string, inner: string, includeEntryId: boolean): RenderBlock =>
  tagBlock("USER", id, inner, includeEntryId);
const aBlock = (id: string, inner: string, includeEntryId: boolean): RenderBlock =>
  tagBlock("ASSISTANT", id, inner, includeEntryId);
const tBlock = (id: string, inner: string, includeEntryId: boolean): RenderBlock =>
  tagBlock("THINKING", id, inner, includeEntryId);

function cBlock(id: string, toolName: string, inner: string, includeEntryId: boolean): RenderBlock {
  const attr = includeEntryId ? ` entryId=${id}` : "";
  return { entryId: id, text: `<TOOLCALL:${toolName}${attr}>${inner}</TOOLCALL>` };
}

function rBlock(id: string, inner: string, isError: boolean, includeEntryId: boolean): RenderBlock {
  const entryAttr = includeEntryId ? ` entryId=${id}` : "";
  const attr = isError ? `${entryAttr} ${ATTR_ERROR}` : entryAttr;
  return { entryId: id, text: `<TOOLRESULT${attr}>${inner}</TOOLRESULT>` };
}

// --- per-entry group rendering ----------------------------------------------

function renderCustomMessageGroup(entry: CustomMessageEntry, includeEntryId: boolean): RenderGroup | null {
  const text = cleanText(entry.content);
  if (text.length === 0) return null;
  return { blocks: [uBlock(entry.id, text, includeEntryId)] };
}

function renderBranchSummaryGroup(entry: BranchSummaryEntry, includeEntryId: boolean): RenderGroup | null {
  const text = stripAnsi(entry.summary);
  if (text.length === 0) return null;
  return { blocks: [uBlock(entry.id, text, includeEntryId)] };
}

/**
 * Render the entry list into entry-bounded groups. Each renderable entry is one
 * group (its blocks never split across chunks). An assistant entry's tool calls
 * absorb their matched tool-result entries into the group (C immediately
 * followed by its R); matched results are consumed and skipped when reached.
 */
export function renderGroups(entries: readonly SessionEntry[], options: ChunkOptions): RenderGroup[] {
  const cap = options.toolBlockCapTokens;
  const includeEntryId = options.includeEntryId;
  const resultByCallId = buildResultIndex(entries);
  const consumedResultIds = new Set<string>();
  const groups: RenderGroup[] = [];

  for (const entry of entries) {
    switch (entry.type) {
      case "message": {
        const blocks = renderMessageBlocks(entry, options, cap, resultByCallId, consumedResultIds);
        if (blocks.length > 0) groups.push({ blocks });
        break;
      }
      case "custom_message": {
        const group = renderCustomMessageGroup(entry, includeEntryId);
        if (group !== null) groups.push(group);
        break;
      }
      case "branch_summary": {
        const group = renderBranchSummaryGroup(entry, includeEntryId);
        if (group !== null) groups.push(group);
        break;
      }
      // operational entries (model_change, thinking_level_change, label,
      // session_info, custom) are not renderable Observer sources — skip.
      default:
        break;
    }
  }
  return groups;
}

function buildResultIndex(entries: readonly SessionEntry[]): Map<string, SessionMessageEntry> {
  const resultByCallId = new Map<string, SessionMessageEntry>();
  for (const entry of entries) {
    if (entry.type !== "message") continue;
    const message = entry.message;
    if (typeof message === "object" && message !== null && message.role === "toolResult") {
      resultByCallId.set(message.toolCallId, entry);
    }
  }
  return resultByCallId;
}

function renderMessageBlocks(
  entry: SessionMessageEntry,
  options: ChunkOptions,
  cap: number | null,
  resultByCallId: Map<string, SessionMessageEntry>,
  consumedResultIds: Set<string>,
): RenderBlock[] {
  const message = entry.message;
  if (typeof message !== "object" || message === null) return [];
  const id = entry.id;
  const includeEntryId = options.includeEntryId;

  if (message.role === "user") {
    const text = cleanText(message.content);
    return text.length > 0 ? [uBlock(id, text, includeEntryId)] : [];
  }

  if (message.role === "toolResult") {
    if (consumedResultIds.has(id)) return []; // already absorbed into its call's group
    const text = capBlock(cleanText(message.content), cap);
    return [rBlock(id, text, message.isError, includeEntryId)];
  }

  if (message.role === "assistant") {
    return renderAssistantBlocks(message, id, options, cap, resultByCallId, consumedResultIds);
  }
  return [];
}

/** The cleaned non-empty text of each text part of an assistant message, in
 *  content order (thinking / tool-call parts skipped). Shared by the chunk
 *  pipeline's assistant renderer and the Selector's text-only preceding-agent
 *  prelude so the text-extraction logic lives in one place. */
function assistantTextParts(message: AssistantMessage): string[] {
  const out: string[] = [];
  for (const part of message.content) {
    if (part.type !== "text") continue;
    const text = cleanText([part]);
    if (text.length > 0) out.push(text);
  }
  return out;
}

function renderAssistantBlocks(
  message: AssistantMessage,
  id: string,
  options: ChunkOptions,
  cap: number | null,
  resultByCallId: Map<string, SessionMessageEntry>,
  consumedResultIds: Set<string>,
): RenderBlock[] {
  const includeEntryId = options.includeEntryId;
  const blocks: RenderBlock[] = [];
  for (const part of message.content) {
    switch (part.type) {
      case "text": {
        const text = cleanText([part]);
        if (text.length > 0) blocks.push(aBlock(id, text, includeEntryId));
        break;
      }
      case "thinking": {
        if (!options.includeThinking) break;
        if (part.redacted === true) break; // redacted always skipped
        const cleaned = sanitizeThinking(part.thinking);
        if (cleaned.length > 0) blocks.push(tBlock(id, cleaned, includeEntryId));
        break;
      }
      case "toolCall": {
        emitToolCallPair(part, id, cap, includeEntryId, resultByCallId, consumedResultIds, blocks);
        break;
      }
      default:
        break;
    }
  }
  return blocks;
}

function emitToolCallPair(
  call: ToolCall,
  callEntryId: string,
  cap: number | null,
  includeEntryId: boolean,
  resultByCallId: Map<string, SessionMessageEntry>,
  consumedResultIds: Set<string>,
  blocks: RenderBlock[],
): void {
  // args are structured JSON (not free text) — capped but not ANSI-stripped
  const argsText = capBlock(JSON.stringify(call.arguments), cap);
  blocks.push(cBlock(callEntryId, call.name, argsText, includeEntryId));

  const resultEntry = resultByCallId.get(call.id);
  if (resultEntry === undefined) return; // orphan call (result absent mid-stream)
  const result = resultEntry.message;
  if (typeof result !== "object" || result === null || result.role !== "toolResult") return;
  const resultText = capBlock(cleanText(result.content), cap);
  blocks.push(rBlock(resultEntry.id, resultText, result.isError, includeEntryId));
  consumedResultIds.add(resultEntry.id);
}

// --- public: flat block list (for render verification) ---------------------

export function renderBlocks(entries: readonly SessionEntry[], options: ChunkOptions): RenderBlock[] {
  return renderGroups(entries, options).flatMap((group) => group.blocks);
}

// --- chunk splitting (entry-bounded) ----------------------------------------

/**
 * Split entries into entry-bounded, token-gated chunks. A whole entry (its
 * group) is never split across chunks. Each chunk reports `allowedIds`: the entryId=
 * ids cited in its blocks (the allowed source-id set the Observer's
 * `record_observations` must draw from).
 */
export function buildChunks(entries: readonly SessionEntry[], options: ChunkOptions): RenderedChunk[] {
  const groups = renderGroups(entries, options);
  const chunks: RenderedChunk[] = [];
  let current: RenderBlock[] = [];
  let currentTokens = 0;

  const flush = (): void => {
    if (current.length === 0) return;
    let text = current.map((block) => block.text).join(BLOCK_SEP);
    const allowedIds = new Set(current.map((block) => block.entryId));
    const firstEntryId = current[FIRST_INDEX]?.entryId ?? "";
    const lastEntryId = current[current.length - 1]?.entryId ?? "";
    // short-id mode: renumber this chunk's entryId= attributes as sequential
    // shorts in first-appearance order and report the short→stored map — the
    // model cites shorts, every stored id stays real (the attr precedes the
    // inner text in every block shape, so the first occurrence per block is
    // always the attribute itself)
    let idMap: ReadonlyMap<string, string> | undefined;
    if (options.shortEntryIds === true) {
      const shortOf = new Map<string, string>();
      const map = new Map<string, string>();
      text = current
        .map((block) => {
          let short = shortOf.get(block.entryId);
          if (short === undefined) {
            short = `e${shortOf.size + 1}`;
            shortOf.set(block.entryId, short);
            map.set(short, block.entryId);
          }
          return block.text.replace(` entryId=${block.entryId}>`, ` entryId=${short}>`);
        })
        .join(BLOCK_SEP);
      idMap = map;
    }
    chunks.push({ text, allowedIds, firstEntryId, lastEntryId, idMap });
    current = [];
    currentTokens = 0;
  };

  for (const group of groups) {
    current.push(...group.blocks);
    // chars/4 over the group's joined text (same as estimateContentTokens on the
    // join) — computed by summing block lengths, avoiding the temp string alloc.
    const groupChars = group.blocks.reduce((sum, block) => sum + block.text.length, 0);
    currentTokens += Math.ceil(groupChars / CHARS_PER_TOKEN_ESTIMATE);
    if (currentTokens >= options.tokenThreshold) flush();
  }
  flush(); // trailing remainder
  return chunks;
}

/**
 * Render an assistant message's TEXT as `<ASSISTANT>text</ASSISTANT>` blocks
 * (text-only — thinking/tool calls dropped), one block per text part (matching
 * the chunk pipeline), with the same ANSI sanitization. Returns "" when the
 * message carries no text. Used by the Selector tail pairing (text-only
 * preceding-agent prelude) — a recall consumer, so it omits `entryId=id`.
 */
export function renderAssistantTextBlock(entry: SessionEntry, includeEntryId: boolean): string {
  if (entry.type !== "message") return "";
  if (entry.message.role !== "assistant") return "";
  return assistantTextParts(entry.message)
    .map((text) => aBlock(entry.id, text, includeEntryId).text)
    .join("");
}

/** Cheap presence predicate: true when the entry is an assistant message with
 *  at least one non-empty cleaned text part. Avoids the full render+join of
 *  `renderAssistantTextBlock` when only presence is needed (e.g. a scan). */
export function hasAssistantText(entry: SessionEntry): boolean {
  if (entry.type !== "message") return false;
  if (entry.message.role !== "assistant") return false;
  return assistantTextParts(entry.message).length > 0;
}

// --- AgentMessage rendering (stage dumps) ------------------------------------

/** AgentMessages carry no entry ids — the produced-message dump render is a
 *  recall-style consumer (no entryId= attributes). */
const DUMP_ID = "";
/** includeEntryId=false for every dump block (same reason as DUMP_ID). */
const DUMP_OMIT_ENTRY_ID = false;

function isUserMessage(message: AgentMessage): message is UserMessage {
  return (message as UserMessage).role === "user";
}

function isAssistantMessage(message: AgentMessage): message is AssistantMessage {
  return (message as AssistantMessage).role === "assistant";
}

function isToolResultMessage(message: AgentMessage): message is ToolResultMessage {
  return (message as ToolResultMessage).role === "toolResult";
}

/** Render `AgentMessage[]` into the chunk tag grammar, full fidelity (no caps,
 *  thinking included, redacted thinking skipped) — the PRODUCED-message dump
 *  renderer. A tool call's matched result is absorbed right after the call
 *  (adjacency unit); an orphan result renders standalone in place. Unknown
 *  message shapes are skipped. */
export function renderAgentMessages(messages: readonly AgentMessage[]): string {
  const resultByCallId = new Map<string, ToolResultMessage>();
  for (const message of messages) {
    if (isToolResultMessage(message)) resultByCallId.set(message.toolCallId, message);
  }
  const consumedResultIds = new Set<string>();
  const blocks: string[] = [];

  const emitResult = (result: ToolResultMessage): void => {
    blocks.push(rBlock(DUMP_ID, cleanText(result.content), result.isError, DUMP_OMIT_ENTRY_ID).text);
    consumedResultIds.add(result.toolCallId);
  };

  for (const message of messages) {
    if (isToolResultMessage(message)) {
      if (consumedResultIds.has(message.toolCallId)) continue; // absorbed into its call
      emitResult(message);
      continue;
    }
    if (isUserMessage(message)) {
      const text = cleanText(message.content);
      if (text.length > 0) blocks.push(uBlock(DUMP_ID, text, DUMP_OMIT_ENTRY_ID).text);
      continue;
    }
    if (!isAssistantMessage(message)) continue;
    for (const part of message.content) {
      switch (part.type) {
        case "text": {
          const text = cleanText([part]);
          if (text.length > 0) blocks.push(aBlock(DUMP_ID, text, DUMP_OMIT_ENTRY_ID).text);
          break;
        }
        case "thinking": {
          if (part.redacted === true) break; // redacted always skipped
          const cleaned = sanitizeThinking(part.thinking);
          if (cleaned.length > 0) blocks.push(tBlock(DUMP_ID, cleaned, DUMP_OMIT_ENTRY_ID).text);
          break;
        }
        case "toolCall": {
          // args are structured JSON — full fidelity, not ANSI-stripped
          blocks.push(cBlock(DUMP_ID, part.name, JSON.stringify(part.arguments), DUMP_OMIT_ENTRY_ID).text);
          const result = resultByCallId.get(part.id);
          if (result !== undefined) emitResult(result);
          break;
        }
        default:
          break;
      }
    }
  }
  return blocks.join(BLOCK_SEP);
}

/** Render the stage INPUT messages verbatim: what the LLM received, exactly as
 *  it received it. Stage inputs are user messages whose string content already
 *  carries its own format (the Observer's chunk-grammar text with entry tags,
 *  the Builder/Selector's rendered views) — wrapping them in message-level tags
 *  would nest same-name tags over that grammar (`…</USER></USER>`, thinking
 *  inside a "USER" wrapper), so no wrapper is added at all. A message with
 *  structured content (not the stage shapes) falls back to the recall-style
 *  block render. */
export function renderStageInputMessages(messages: readonly AgentMessage[]): string {
  const parts: string[] = [];
  for (const message of messages) {
    if (isUserMessage(message) && typeof message.content === "string") {
      const text = stripAnsi(message.content);
      if (text.length > 0) parts.push(text);
      continue;
    }
    const rendered = renderAgentMessages([message]);
    if (rendered.length > 0) parts.push(rendered);
  }
  return parts.join(BLOCK_SEP);
}

